// Pair of nonadjacent roots sharing four neighbors. Enumerate six exclusive rows, then four common rows with prescribed column degrees. Final independent-eight test on the full graph.
use std::io::{self,BufRead};
fn independent(g:&[u32],mut p:u32,k:u32)->bool{if k==0{return true}while p.count_ones()>=k{let i=p.trailing_zeros() as usize;p&=p-1;if independent(g,p&!g[i],k-1){return true}}false}
struct Search{a:Vec<u32>,cross:[u32;6],opt:[Vec<u32>;6],q4:Vec<u32>,q5:Vec<u32>,pairs:std::collections::HashMap<u64,Vec<(u32,u32)>>,ok:Vec<Vec<Vec<Vec<u64>>>>,indices:[usize;6],rows:[u32;6],stats:[u64;4]}
fn pack(s:u32)->u64{let mut r=0;for j in 0..16{r|=(((s>>j)&1)as u64)<<(4*j)}r}
impl Search{fn visit(&mut self,pos:usize){if pos==6{self.stats[0]+=1;let mut need=0u64;for j in 0..16{let used=self.a[j].count_ones()+self.rows.iter().filter(|&&s|s>>j&1==1).count() as u32;if !(3..=7).contains(&used){return}need|=((7-used)as u64)<<(4*j)}self.stats[1]+=1;for (&key,ps) in &self.pairs{if key>need{continue}let other=need-key;if other<key{continue}if let Some(qs)=self.pairs.get(&other){for &(s,t) in ps{for &(u,v) in qs{self.stats[2]+=1;let mut g=self.a.clone();g.resize(28,0);for(i,&r)in self.rows.iter().chain([s,t,u,v].iter()).enumerate(){let h=16+i;g[h]=r;for j in 0..16{if r>>j&1!=0{g[j]|=1<<h}}}for i in 0..6{g[16+i]|=self.cross[i]<<16;}for i in 0..10{for j in 0..2{if i>=6||i/3==j{g[16+i]|=1<<(26+j);g[26+j]|=1<<(16+i)}}}assert!(g.iter().all(|x|x.count_ones()==7));if !independent(&g,(1<<28)-1,8){self.stats[3]+=1}}}}}return}
// Interleave the two triples to enforce red cross-edge disjointness early.
let h=[0,3,1,4,2,5][pos];let order=[0,3,1,4,2,5];let others:Vec<_>=order[..pos].iter().filter(|&&i|i/3==h/3).map(|&i|self.rows[i]).collect();for w in 0..(self.opt[h].len()+63)/64{let mut mask=!0u64;for &i in &order[..pos]{mask &=self.ok[i][h][self.indices[i]][w]}while mask!=0{let k=w*64+mask.trailing_zeros() as usize;mask&=mask-1;if k>=self.opt[h].len(){break}let s=self.opt[h][k];if others.len()==2&&self.q4.iter().any(|&q|q&(s|others[0]|others[1])==0){continue}self.indices[h]=k;self.rows[h]=s;self.visit(pos+1)}}}}
// Bipartite templates modulo independent permutations of the triples and exchange of sides.
fn templates(edges:u32)->Vec<u32>{let perms=[[0,1,2],[0,2,1],[1,0,2],[1,2,0],[2,0,1],[2,1,0]];let mut out=Vec::new();for m in 0u32..512{if m.count_ones()!=edges{continue}let mut low=m;for p in perms{for q in perms{let(mut v,mut t)=(0,0);for i in 0..3{for j in 0..3{let b=(m>>(3*i+j))&1;v|=b<<(3*p[i]+q[j]);t|=b<<(3*q[j]+p[i]);}}low=low.min(v).min(t)}}if low==m{out.push(m)}}out}
fn main(){for l in io::stdin().lock().lines(){let a:Vec<u32>=l.unwrap().split_whitespace().map(|s|s.parse().unwrap()).collect();assert_eq!(a.len(),16);let e=a.iter().map(|v|v.count_ones()).sum::<u32>()/2;assert!((32..=37).contains(&e));let mut sets=vec![0u32];for(i,&v)in a.iter().enumerate(){for j in 0..sets.len(){if sets[j]&v==0{sets.push(sets[j]|1<<i)}}}let five:Vec<_>=sets.iter().copied().filter(|s|s.count_ones()==5).collect();let mut pairs=std::collections::HashMap::<u64,Vec<(u32,u32)>>::new();for(i,&s)in five.iter().enumerate(){for &t in &five[i..]{pairs.entry(pack(s)+pack(t)).or_default().push((s,t))}}let mut totals=[0u64;4];for mask in templates(e-28){let mut cross=[0u32;6];for i in 0..3{for j in 3..6{if mask>>(3*i+j-3)&1!=0{cross[i]|=1<<j;cross[j]|=1<<i}}}let mut x=Search{a:a.clone(),cross,opt:std::array::from_fn(|i|sets.iter().copied().filter(|s|s.count_ones()==6-cross[i].count_ones()).collect()),q4:sets.iter().copied().filter(|s|s.count_ones()==4).collect(),q5:five.clone(),pairs:pairs.clone(),ok:vec![],indices:[0;6],rows:[0;6],stats:[0;4]};x.ok=(0..6).map(|i|(0..6).map(|j|x.opt[i].iter().map(|s|{let mut m=vec![0;(x.opt[j].len()+63)/64];for(k,t)in x.opt[j].iter().enumerate(){if (cross[i]>>j&1==0||s&t==0)&&(i/3!=j/3||x.q5.iter().all(|q|q&(s|t)!=0)){m[k/64]|=1<<(k%64)}}m}).collect()).collect()).collect();x.visit(0);for j in 0..4{totals[j]+=x.stats[j]}}println!("{} {} {} {}",totals[0],totals[1],totals[2],totals[3]);}}
